```ts
// ── mapEntryIdsToMessageIndices (entry-id → message-index mapping; spec/06 §6; P1.M2.T1.S2) ─────────

/**
 * mapEntryIdsToMessageIndices — map a SET of branch-entry ids to their CURRENT message indices
 * (spec/06-context-filter.md §6; generalizes resolveCheckpoint's ctxEntries-walk). PURE + Pi-FREE.
 *
 * ALGORITHM (mirrors resolveCheckpoint step 4 — same ctxEntries filter, same msgCursor, same guard order):
 *   1. Defensive: non-array messages/branchEntries → []; normalize entryIds (Set<string> | string[]) into a
 *      Set<string> (non-string/empty members skipped); empty Set → [].
 *   2. ctxEntries = branchEntries (root→leaf) filtered to context-producing types (reuse isContextProducingType).
 *   3. Walk ctxEntries with msgCursor. For each entry: y = entryMessageYield(e);
 *      - y < 0 (compaction/unknown → indeterminate) → BREAK (return indices collected so far — never guess).
 *      - msgCursor + y > messages.length (alignment lost) → BREAK.
 *      - else if entry.id ∈ idSet → collect the range [msgCursor .. msgCursor+y-1] (yield=1 today → just msgCursor).
 *      - msgCursor += y.
 *   4. Return ascending + unique indices ([...new Set(collected)].sort(ascending)).
 *
 * DIFFERS from resolveCheckpoint ONLY in collection policy: resolveCheckpoint REFUSES (null) on any indeterminacy
 * in the walked range; THIS helper returns PARTIAL results (the deterministically-mappable ids before the
 * indeterminate entry). resolveCheckpoint recovers its refuse-semantic by calling this with [targetId] and
 * treating an empty result as 'refuse' (refactored call site below).
 *
 * Pure + defensive: null/non-array messages/branchEntries/entryIds, malformed entries, throwing-Proxy entries
 * (readOwn swallows), and duplicate ids are all handled gracefully — NEVER throws (E13; context-handler hot path).
 *
 * @param messages      the message list; non-array → []
 * @param branchEntries getBranch() output (root→leaf); non-array → []
 * @param entryIds      the entry ids to resolve (Set<string> | string[]); anything else → []
 * @returns ascending + unique message indices for the deterministically-mappable requested ids
 */
export function mapEntryIdsToMessageIndices(
  messages: MessageLike[],
  branchEntries: BranchEntry[],
  entryIds: Set<string> | string[],
): number[] {
  if (!Array.isArray(messages) || !Array.isArray(branchEntries)) return [];
  const idSet = normalizeEntryIdSet(entryIds); // Set<string>; non-array/non-Set → empty
  if (idSet.size === 0) return [];

  const ctxEntries = branchEntries.filter((e) =>
    isContextProducingType(isRecord(e) ? readOwn(e, "type") : undefined),
  );

  const collected: number[] = [];
  let msgCursor = 0;
  for (const e of ctxEntries) {
    const y = entryMessageYield(e); // 1 for message/custom_message/branch_summary; -1 for compaction/unknown
    if (y < 0) break; // indeterminate → STOP (keep collected so far; never guess, never throw)
    if (msgCursor + y > messages.length) break; // alignment lost → STOP
    const id = isRecord(e) ? readOwn(e, "id") : undefined;
    if (typeof id === "string" && id.length > 0 && idSet.has(id)) {
      for (let k = msgCursor; k < msgCursor + y; k++) collected.push(k); // range [msgCursor .. msgCursor+y-1]
    }
    msgCursor += y;
  }

  return [...new Set(collected)].sort((a, b) => a - b); // ascending + unique (defensive dedupe)
}

/** Module-private: normalize entryIds (Set<string> | string[]) into a Set<string>; anything else → empty Set. */
function normalizeEntryIdSet(entryIds: unknown): Set<string> {
  const out = new Set<string>();
  if (entryIds instanceof Set) {
    for (const id of entryIds) if (typeof id === "string" && id.length > 0) out.add(id);
  } else if (Array.isArray(entryIds)) {
    for (const id of entryIds) if (typeof id === "string" && id.length > 0) out.add(id);
  }
  return out;
}
```

